-- The inventory template, as Postgres tables. Made by baseToSql (@svgrid/enterprise/base);
-- the svgrid: comments keep what SQL has no type for, so baseFromDatabase opens it as the same base.

create table "items" (
  "id" text primary key default gen_random_uuid()::text,
  "svgrid_order" bigint generated always as identity,
  "item" text,
  "photo" jsonb,
  "category" text,
  "location" text,
  "supplier_id" text,
  "qty" double precision,
  "unit_cost" double precision,
  "condition" double precision,
  "checked_out" text,
  "audited" date,
  "sku" text
);
create table "suppliers" (
  "id" text primary key default gen_random_uuid()::text,
  "svgrid_order" bigint generated always as identity,
  "name" text,
  "email" text,
  "lead_days" double precision
);

comment on column "items"."item" is 'svgrid:{"field":"item","header":"Item","width":230,"fieldType":"text"}';
comment on column "items"."photo" is 'svgrid:{"field":"photo","header":"Photo","width":104,"fieldType":"attachment","fieldProps":{"accept":"image/*","maxFiles":3}}';
comment on column "items"."category" is 'svgrid:{"field":"category","header":"Category","width":150,"fieldType":"singleSelect","fieldProps":{"options":[{"value":"Furniture","color":"#c46f4e"},{"value":"Lighting","color":"#fcb400"},{"value":"Kitchen","color":"#20c933"},{"value":"Audio","color":"#8b46ff"},{"value":"Decor","color":"#2d7ff9"},{"value":"Plants","color":"#20d9d2"}]}}';
comment on column "items"."location" is 'svgrid:{"field":"location","header":"Location","width":130,"fieldType":"singleSelect","fieldProps":{"options":[{"value":"Studio A","color":"#2d7ff9"},{"value":"Studio B","color":"#8b46ff"},{"value":"Warehouse","color":"#94a3b8"},{"value":"Showroom","color":"#ff6f2c"}]}}';
comment on column "items"."supplier_id" is 'svgrid:{"field":"supplier","header":"Supplier","width":180,"fieldType":"link","fieldProps":{"table":"suppliers","multiple":false,"inverse":"items"}}';
comment on column "items"."qty" is 'svgrid:{"field":"qty","header":"Qty","width":90,"fieldType":"number","fieldProps":{"format":"integer","summary":"sum"}}';
comment on column "items"."unit_cost" is 'svgrid:{"field":"unitCost","header":"Unit cost","width":132,"fieldType":"number","fieldProps":{"format":"currency","symbol":"$","precision":2}}';
comment on column "items"."condition" is 'svgrid:{"field":"condition","header":"Condition","width":130,"fieldType":"rating","fieldProps":{"max":5,"color":"#20c933"}}';
comment on column "items"."checked_out" is 'svgrid:{"field":"checkedOut","header":"Checked out to","width":170,"fieldType":"user"}';
comment on column "items"."audited" is 'svgrid:{"field":"audited","header":"Last counted","width":150,"fieldType":"date","fieldProps":{"dateFormat":"friendly"}}';
comment on column "items"."sku" is 'svgrid:{"field":"sku","header":"SKU","width":120,"fieldType":"barcode"}';
comment on table "items" is 'svgrid:{"v":1,"name":"Items","position":0,"primaryField":"item","order":["item","photo","category","location","supplier","qty","unitCost","value","condition","checkedOut","audited","sku"],"extra":[{"field":"value","header":"Stock value","width":150,"fieldType":"formula","fieldProps":{"formula":"{Qty} * {Unit cost}","result":"currency","precision":2,"summary":"sum"}}],"views":[{"id":"stock","name":"Stock by category","type":"grid","state":{"sorting":[{"id":"category","desc":false},{"id":"item","desc":false}],"grouping":["category"],"columnWidths":{"item":230,"photo":104,"category":150,"location":130,"supplier":180,"qty":90,"unitCost":132,"value":150,"condition":130,"checkedOut":170,"audited":150,"sku":120},"columnPinning":{"left":["item"],"right":[]},"columnOrder":["item","photo","category","location","supplier","qty","unitCost","value","condition","checkedOut","audited","sku"],"hiddenColumns":[],"globalFilter":"","columnFilters":{},"facetFilters":{}},"color":{"mode":"none"},"rowHeight":44},{"id":"photos","name":"Photos","type":"gallery","coverField":"photo"},{"id":"where","name":"By location","type":"kanban","stackBy":"location"},{"id":"units","name":"Units by location","type":"chart","chart":{"kind":"bar","x":"location","y":"qty"}},{"id":"reorder","name":"Reorder","type":"grid","color":{"mode":"conditions","rules":[{"color":"#f82b60","condition":{"column":"qty","kind":"number","op":"eq","value":0}},{"color":"#fcb400","condition":{"column":"qty","kind":"number","op":"lte","value":3}}]},"state":{"sorting":[{"id":"qty","desc":false}],"advancedFilter":{"kind":"fieldFilter","conjunction":"and","conditions":[{"column":"qty","kind":"number","op":"lte","value":3}]}}},{"id":"add","name":"Add an item","type":"form","formFields":["item","photo","category","location","supplier","qty","unitCost"],"formDescription":"New stock or equipment. It shows in the list as soon as you submit."}]}';
comment on column "suppliers"."name" is 'svgrid:{"field":"name","header":"Supplier","width":200,"fieldType":"text"}';
comment on column "suppliers"."email" is 'svgrid:{"field":"email","header":"Orders","width":260,"fieldType":"email"}';
comment on column "suppliers"."lead_days" is 'svgrid:{"field":"leadDays","header":"Lead time (days)","width":150,"fieldType":"number","fieldProps":{"format":"integer"}}';
comment on table "suppliers" is 'svgrid:{"v":1,"name":"Suppliers","position":1,"primaryField":"name","order":["name","email","leadDays","items","itemCount","units"],"extra":[{"field":"items","header":"Items","width":320,"fieldType":"link","fieldProps":{"table":"items","multiple":true,"inverse":"supplier"}},{"field":"itemCount","header":"Item count","width":120,"fieldType":"count","fieldProps":{"linkField":"items"}},{"field":"units","header":"Units in stock","width":140,"fieldType":"rollup","fieldProps":{"linkField":"items","field":"qty","aggregation":"SUM"}}],"views":[{"id":"suppliers","name":"All suppliers","type":"grid"}]}';

